INSERT INTO public.products (slug, title, subtitle, description, composition, care, price, old_price, category_id, tags, images, stock, published, featured) VALUES
('balzam-pervaya-zelen', 'Бальзам для рук «Первая зелень»', 'питание и мягкость каждый день', 'Плотный, но быстро впитывающийся бальзам с маслом ши и вытяжкой молодых листьев берёзы. Успокаивает сухую кожу после весеннего ветра и городской воды.', 'Масло ши, масло сладкого миндаля, пчелиный воск, экстракт листьев берёзы, эфирное масло петитгрейна.', 'Хранить при температуре до 25 °C, вдали от прямого солнца. Использовать в течение 12 месяцев после открытия.', 890, 990, (SELECT id FROM public.categories WHERE slug = 'uhod-kosmetika'), ARRAY['уход','руки','натуральное'], ARRAY['/products/balm.jpg'], 40, true, true),
('sashe-sirenevyy-vecher', 'Саше «Сиреневый вечер»', 'аромат для шкафа и белья', 'Льняной мешочек с сушёными соцветиями сирени и лаванды. Нежный аромат держится до трёх месяцев и мягко освежает бельё, шарфы и книги.', 'Лён, сушёные соцветия сирени и лаванды, эфирное масло лаванды.', 'Сминайте мешочек в руках, чтобы освежить аромат. Не мочить.', 640, NULL, (SELECT id FROM public.categories WHERE slug = 'aromaty-svechi'), ARRAY['аромат','саше','сирень'], ARRAY['/products/sachet.jpg'], 55, true, false),
('salfetki-cheremuha', 'Набор льняных салфеток «Черёмуха»', 'четыре салфетки для весеннего стола', 'Мягкий умягчённый лён пастельных оттенков: молочный, пудровый и шалфейный. Четыре салфетки 40×40 см, которые заменяют бумажные и становятся только приятнее после стирок.', '100% лён, умягчённая ткань, ручная обработка края.', 'Стирка при 40 °C, глажка с паром. Не использовать хлорные средства.', 1290, 1490, (SELECT id FROM public.categories WHERE slug = 'dom-kuhnya'), ARRAY['дом','стол','лён'], ARRAY['/products/napkins.jpg'], 18, true, false),
('trubochka-ruchey', 'Трубочка с ёршиком «Ручей»', 'стальная, на все напитки', 'Многоразовая трубочка из пищевой нержавеющей стали с ёршиком и льняным чехлом. Помещается в сумку и заменяет сотни одноразовых.', 'Нержавеющая сталь 18/8, нейлоновый ёршик, чехол из льна.', 'Промывайте ёршиком после каждого использования, можно мыть в посудомоечной машине.', 390, NULL, (SELECT id FROM public.categories WHERE slug = 'zero-waste'), ARRAY['zero waste','с собой','сталь'], ARRAY['/products/straw.jpg'], 90, true, false);